def max_sum(arr, n):
    """Write a function to find the maximum sum of bi-tonic sub-sequence for the given array."""
    if arr is None or n is None or n <= 0:
        return 0
    values = list(arr[:n])
    if not values:
        return 0
    size = len(values)
    increasing = values[:]
    for i in range(size):
        for j in range(i):
            if values[j] < values[i] and increasing[j] + values[i] > increasing[i]:
                increasing[i] = increasing[j] + values[i]
    decreasing = values[:]
    for i in range(size - 1, -1, -1):
        for j in range(i + 1, size):
            if values[j] < values[i] and decreasing[j] + values[i] > decreasing[i]:
                decreasing[i] = decreasing[j] + values[i]
    return max(increasing[i] + decreasing[i] - values[i] for i in range(size))
